class HostApi {
  // Bridge to app.py (pywebview). Graphs are generated by the python worker per slot (from that
  // slot's yaml) and live only in memory here; python keeps the on-disk cache in ~/.cache.

  /** @type {Record<string, any>} conn.id -> flat rules graph */
  static graphs = {}
  /** @type {Record<string, string>} conn.id -> last build error */
  static errors = {}
  /** @type {Set<string>} conn ids with a generation in flight */
  static building = new Set()
  /** @type {{game: string, version: string}[] | null} */
  static worlds = null

  static async init() {
    // window.pywebview exists before its api methods are injected, so wait for the method itself
    if (typeof window.pywebview?.api?.list_worlds !== "function") {
      await new Promise((resolve) =>
        window.addEventListener("pywebviewready", resolve, {
          once: true,
        }),
      )
    }
    document.getElementById("notifBtn").style.display = "none" // notifications go through python
    document.getElementById("swbtn").style.display = "none"
    HostApi.worlds = await window.pywebview.api.list_worlds()
    SlotsUI.populateGameSelect()
  }

  /**
   * @param {SlotConnection} conn
   * @param {boolean} force regenerate even if python has a cached graph
   */
  static async ensureGraph(conn, force = false) {
    if (HostApi.graphs[conn.id] && !force) return
    HostApi.building.add(conn.id)
    delete HostApi.errors[conn.id]
    SlotsUI.renderSlots()
    try {
      const r = await window.pywebview.api.build({
        game: conn.game,
        playerName: conn.playerName,
        yamlPath: conn.yamlPath,
        force,
      })
      if (r.error) {
        HostApi.errors[conn.id] = r.error
        return
      }
      const cc = window.db.connections[conn.id]
      if (!cc) return // slot was removed while generating
      HostApi.graphs[conn.id] = r.graph
      cc.yamlPath = r.yamlPath
      cc.cacheKey = r.key
      cc.optionsSource = r.optionsSource
    } catch (e) {
      HostApi.errors[conn.id] = String(e?.message ?? e)
      error(e)
    } finally {
      HostApi.building.delete(conn.id)
      SlotsUI.renderSlots()
    }
  }

  // Throws the old graph away and builds a new one (new yaml, or the world's code changed).
  /**
   * @param {SlotConnection} conn
   */
  static async regenerate(conn) {
    delete HostApi.graphs[conn.id]
    await HostApi.ensureGraph(conn, true)
    const rt = Connections.runtime[conn.id]
    if (rt && HostApi.graphs[conn.id]) {
      RequirementGroups.maybeRecomputeProgression(conn, rt)
      CheeseTrackers.ctAutoSync(conn)
    }
    if (db.currentMapConnId === conn.id) {
      if (SlotSync.appEl.classList.contains("visible"))
        SlotSync.openMapForSlot(conn)
      else SlotSync.syncFromSlot(conn)
    }
  }

  // Lets python delete cached graphs no slot points at any more.
  static async gc() {
    const keys = Object.values(window.db.connections).map(
      (c) => c.cacheKey,
    )
    await window.pywebview.api.gc(keys.filter((k) => k))
  }
}
